using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Drawing.Imaging;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Web.Script.Serialization;using System.Windows.Forms;
internal static class PetMotionEntryTests {
 const BindingFlags Hidden=BindingFlags.NonPublic|BindingFlags.Instance;static int checks;
 static void Need(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
 static T Field<T>(object target,string name){return (T)target.GetType().GetField(name,Hidden).GetValue(target);}
 static bool Same(Bitmap a,Bitmap b){for(int y=0;y<a.Height;y+=3)for(int x=0;x<a.Width;x+=3)if(a.GetPixel(x,y)!=b.GetPixel(x,y))return false;return true;}
 static object Work(PetPack pack){
  var output=new List<object>();foreach(string phase in new[]{"thinking","working","result"}){var d=new PetAnimationDirector(pack,new PetBehaviorProfile{SleepSeconds=86400},3);var m=new PetMotion(1);double now=.001;d.Tick(now,m,phase,false,false,false);var rows=new List<int>();for(int i=0;i<18;i++){now+=d.Duration(d.Row)+.02;d.Tick(now,m,phase,false,false,false);rows.Add(d.Row);}var candidates=d.Spec.work[1].Concat(d.Spec.work[2]).Concat(d.Spec.work[3]).Distinct().Select(v=>pack.Actions==null?v:9+v).ToArray();var loops=rows.Skip(2).ToArray();if(candidates.Length>1){Need(loops.Zip(loops.Skip(1),(a,b)=>a!=b).All(v=>v),"Work repeats in "+pack.Id+" "+phase);Need(loops.Distinct().Count()>=Math.Min(4,candidates.Length),"Work does not rotate its full pool: "+pack.Id+" "+phase);}Need(loops.All(candidates.Contains),"Work rotation includes a non-work action");int current=d.Row,generation=d.Generation;d.Tick(now+d.Duration(current)*.25,m,"success",false,false,false);Need(d.Generation==generation,"Completion cuts an unfinished work clip");d.Tick(now+d.Duration(current)+.03,m,"success",false,false,false);Need(d.Spec.work[4].Any(v=>d.Row==(pack.Actions==null?v:9+v)),"Task completion animation missing");output.Add(new{phase,distinct=loops.Distinct().Count(),rows=loops});}return new{pet=pack.Id,work=output};
 }
 static object ImageDrag(PetPack pack,string folder){
  var director=new PetAnimationDirector(pack,new PetBehaviorProfile(),3);int row=director.DragRow;var clock=Stopwatch.StartNew();using(var atlas=new PetAtlas(pack)){
   atlas.PrepareDrag(row);double returned=clock.Elapsed.TotalMilliseconds;clock.Restart();while(!atlas.DragReady&&clock.ElapsedMilliseconds<5000)Thread.Sleep(5);Need(atlas.DragReady&&atlas.DragPreparationError==null,"Drag preparation failed: "+pack.Id+" "+atlas.DragPreparationError);long prepared=clock.ElapsedMilliseconds;
   Need(returned<1000,"Prewarm caller blocked unexpectedly");atlas.DragHeld=true;RectangleF bounds=atlas.ContentBounds(row);Need(bounds.Width>0&&bounds.Height>0,"Prepared silhouette missing");
   if(pack.Format=="animated-gif-set"){var warm=Field<Bitmap>(atlas,"warmedDragGif");Need(warm!=null,"GIF drag not preloaded");atlas.Frame(row,0);Need(Object.ReferenceEquals(warm,atlas.Bitmap),"Drag reopened GIF instead of reusing warm clip");atlas.Frame(0,0);Need(Object.ReferenceEquals(atlas.Bitmap,Field<Bitmap>(atlas,"idleGif")),"Release reopens idle GIF");atlas.Frame(row,0);Need(Object.ReferenceEquals(warm,atlas.Bitmap),"Repeated drag reloads GIF");}
   using(var image=new Bitmap(384,416))using(var g=Graphics.FromImage(image)){clock.Restart();atlas.Draw(g,new Rectangle(0,0,384,416),row,0);double first=clock.Elapsed.TotalMilliseconds;Need(first<100,"First drag frame stalls: "+pack.Id+" "+first);double duration=director.Duration(row);g.Clear(Color.Transparent);atlas.Draw(g,new Rectangle(0,0,384,416),row,duration+.1);using(var end=(Bitmap)image.Clone()){g.Clear(Color.Transparent);atlas.Draw(g,new Rectangle(0,0,384,416),row,duration+5);Need(Same(end,image),"Held drag loops back to initial pose: "+pack.Id);}image.Save(Path.Combine(folder,pack.Id+"-held-drag.png"));return new{pet=pack.Id,prepareMs=prepared,firstDragFrameMs=first,reusesWarmClip=true,heldPoseStable=true};}
  }
 }
 static object VideoDrag(PetPack pack,string folder){var d=new PetAnimationDirector(pack,new PetBehaviorProfile(),2);using(var atlas=new PetAtlas(pack))using(var image=new Bitmap(640,360))using(var g=Graphics.FromImage(image)){
  atlas.PrepareDrag(d.DragRow);var clock=Stopwatch.StartNew();while(!atlas.DragReady&&clock.ElapsedMilliseconds<8000)Thread.Sleep(5);Need(atlas.DragReady,"Video drag not ready");atlas.DragHeld=true;atlas.BeginVideo(d.DragRow,1,true);var render=Stopwatch.StartNew();atlas.Draw(g,new Rectangle(0,0,640,360),d.DragRow,0);long first=render.ElapsedMilliseconds;Need(first<100,"Video first drag frame stalls");clock.Restart();double reached=-1;while(clock.Elapsed.TotalSeconds<1){atlas.Draw(g,new Rectangle(0,0,640,360),d.DragRow,clock.Elapsed.TotalSeconds);if(atlas.VideoPlaybackTime>=3.45&&reached<0)reached=clock.Elapsed.TotalSeconds;Thread.Sleep(8);}Need(reached>=0&&reached<.6,"Video flying intro is still delayed: "+reached);double held=atlas.VideoPlaybackTime;Thread.Sleep(80);atlas.Draw(g,new Rectangle(0,0,640,360),d.DragRow,1.2);Need(Math.Abs(atlas.VideoPlaybackTime-held)<.05,"Video drag pose does not hold");Need(atlas.VideoError==null,"Video decoder error");atlas.DragHeld=false;atlas.ReleaseDragFrame();Need(Field<Bitmap>(atlas,"videoFrame")==null&&Field<Bitmap>(atlas,"previousVideo")==null,"Release retains flight frame");image.Save(Path.Combine(folder,"video-held-drag.png"));return new{pet=pack.Id,firstDragFrameMs=first,heldPoseReachedMs=(int)(reached*1000),releaseStopsFlight=true};}}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();string root=args[0],state=args[1],report=args[2],folder=Path.GetDirectoryName(report);string decoder=Directory.GetFiles(Path.Combine(state,"runtime"),"ffmpeg.exe",SearchOption.AllDirectories).First();typeof(PetMediaRuntime).GetField("cached",BindingFlags.NonPublic|BindingFlags.Static).SetValue(null,decoder);var packs=PetPack.Discover(root,state).Where(p=>p.Available).ToArray();var work=packs.Select(Work).ToArray();var drag=new List<object>();foreach(var pack in packs)drag.Add(pack.Format=="transparent-video-set"?VideoDrag(pack,folder):ImageDrag(pack,folder));var m=new PetMotion(1){Pressed=true};m.StepPress(.08);float pressed=m.PressScale;m.Drag(new PointF(10,10),new Size(40,50),new Rectangle(0,0,400,500));Need(m.PressScale==pressed,"Starting drag resets press scale");m.Pressed=false;m.StepPress(.016);Need(m.PressScale>pressed&&m.PressScale<1,"Press recovery is not gradual");float before=m.PressScale;m.Drop(new PointF(200,0));Need(m.PressScale==before,"Release with inertia snaps scale");Need(m.Sliding,"Inertia no longer works");
  string json=new JavaScriptSerializer().Serialize(new{pass=true,checks,work,drag,pressContinuity=true,noVisibleWindows=true,actualSettingsChanged=false});File.WriteAllText(report,json);Console.WriteLine(json);return 0;
 }catch(Exception error){File.WriteAllText(args[2],new JavaScriptSerializer().Serialize(new{pass=false,checks,error=error.ToString()}));Console.Error.WriteLine(error);return 1;}}
}
